    .dialog-title {
      margin: 0 0 10px;
      font-size: 26px;
      letter-spacing: -0.03em;
    }

    .dialog-copy {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }

    .button.secondary {
      border: 1px solid var(--border);
      background: rgba(255, 255, 255, 0.06);
    }

    .button.danger {
      background: linear-gradient(135deg, var(--danger), var(--danger-dark));
      font-weight: 700;
    }

    @keyframes enter {
      from {
        opacity: 0;
        transform: translateY(10px) scale(0.98);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    @media (max-width: 620px) {
      .page {
        padding: 16px;
      }

      .details,
      .dialog-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .trigger,
      .button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const state = {
      isDialogOpen: false
    };

    const image = {
      title: "Alpine Lake",
      meta: "Saved to Landscape Library · 4.8 MB"
    };

    function ImagePreview({ title, meta }) {
      return `
        <section class="preview-card" aria-labelledby="image-title">
          <div class="image-frame" role="img" aria-label="A calm alpine lake at sunset">
            <span class="image-badge">Image preview</span>
          </div>
          <div class="details">
            <div>
              <h1 class="title" id="image-title">${title}</h1>
              <p class="meta">${meta}</p>
            </div>
            <button class="trigger" type="button" data-action="open-dialog">
              Delete image
            </button>
          </div>
        </section>
      `;
    }

    function DeleteDialog({ open }) {
      return `
        <div class="modal-root" ${open ? "" : "hidden"} aria-hidden="${open ? "false" : "true"}">
          <div class="modal-backdrop" data-action="close-dialog"></div>
          <section
            class="dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="delete-dialog-title"
            aria-describedby="delete-dialog-copy"
          >
            <div class="dialog-icon" aria-hidden="true">!</div>
            <h2 class="dialog-title" id="delete-dialog-title">Delete this image?</h2>
            <p class="dialog-copy" id="delete-dialog-copy">
              This will permanently remove "${image.title}" from your library.
              You cannot undo this action.
            </p>
            <div class="dialog-actions">
              <button class="button secondary" type="button" data-action="close-dialog">Cancel</button>
              <button class="button danger" type="button" data-action="confirm-delete">Delete image</button>
            </div>
          </section>
        </div>
      `;
    }

    function App() {
      return `
        <div class="page">
          ${ImagePreview(image)}
          ${DeleteDialog({ open: state.isDialogOpen })}
        </div>
      `;
    }

    function setDialogOpen(isOpen) {
      state.isDialogOpen = isOpen;
      render();

      if (isOpen) {
        document.querySelector('[data-action="close-dialog"]').focus();
      } else {
        document.querySelector(".trigger").focus();
      }
    }

    function handleClick(event) {
      const action = event.target.closest("[data-action]")?.dataset.action;

      if (action === "open-dialog") {
        setDialogOpen(true);
      }

      if (action === "close-dialog" || action === "confirm-delete") {
        setDialogOpen(false);
      }
    }

