      if (event.key === "Escape" && state.isDialogOpen) {
        setDialogOpen(false);
      }
    }

    function render() {
      document.getElementById("app").innerHTML = App();
    }

    document.addEventListener("click", handleClick);
    document.addEventListener("keydown", handleKeydown);
